function panel(id,content){const p=document.createElement('section');p.id='lesson-'+id;p.className='course-panel';p.innerHTML=content;main.insertBefore(p,footer);return p;}
const intro=(n,title,description,time)=>`<div class="lesson-intro"><div><div class="eyebrow">LESSON ${n} / LEARN BY DOING</div><h1>${title}</h1><p>${description}</p></div><span class="tag">${time} · INTERACTIVE</span></div>`;
