const componentIcon=role=>`<span class="component-icon" aria-hidden="true"><svg viewBox="0 0 40 40" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${{frontend:'<rect x="4" y="6" width="32" height="25" rx="3"/><path d="M4 13h32M15 36h10M20 31v5M9 9.5h1M13 9.5h1M15 19l-4 3 4 3M25 19l4 3-4 3"/>',backend:'<rect x="7" y="4" width="26" height="32" rx="3"/><path d="M7 15h26M7 25h26M12 9h1M12 20h1M12 30h1M20 9h7M20 20h7M20 30h7"/>',database:'<ellipse cx="20" cy="9" rx="13" ry="5"/><path d="M7 9v22c0 7 26 7 26 0V9M7 20c0 7 26 7 26 0"/>'}[role]}</svg></span>`;
panel('foundations',intro('01','One app. Two sides of the conversation.','Change a request, follow it through an API, and watch the frontend react to the response.','10 MIN')+`
<div class="learning-grid"><div class="lab-card"><div class="lesson-controls"><label>Try a scenario <select id="api-scenario"><option value="list">Load notes · GET</option><option value="create">Create a note · POST</option><option value="auth">Missing login · 401</option><option value="missing">Unknown route · 404</option><option value="invalid">Invalid note · 422</option><option value="offline">Server unavailable · 503</option></select></label><button id="api-send" class="primary">Send request ↗</button><button id="api-next" class="secondary">Next step →</button><button id="api-reset" class="secondary">Reset</button></div>
<div class="request-fields"><label class="field-label">Method<input id="api-method" value="GET" readonly></label><label class="field-label">Resource<input id="api-path" value="/api/notes" readonly></label></div><label class="field-label" for="note-text">Note text (used by POST)</label><input id="note-text" value="Learn how APIs work" maxlength="100" style="width:100%;padding:10px;background:#111519;border:1px solid #424b57;border-radius:5px;color:#edf2fa;font:16px inherit">
<div class="api-flow"><button class="role-card" data-role="frontend">${componentIcon('frontend')}<strong>Frontend</strong><span class="component-location">IN THE BROWSER</span><p>Shows the page.<br>Handles your clicks.</p></button><div class="flow-wire" id="api-wire-1"><span>HTTP</span></div><button class="role-card" data-role="backend">${componentIcon('backend')}<strong>Backend / API</strong><span class="component-location">ON THE SERVER</span><p>Checks the request.<br>Runs application logic.</p></button><div class="flow-wire" id="api-wire-2"><span>QUERY</span></div><button class="role-card" data-role="database">${componentIcon('database')}<strong>Database</strong><span class="component-location">DATA STORAGE</span><p>Reads records.<br>Saves your changes.</p></button></div>
<div id="api-status" class="state-note" aria-live="polite"></div><div class="api-browser" aria-label="Interactive web browser simulation"><div class="browser-tabs">${windowDots}<span class="browser-tab"><span class="tab-favicon" aria-hidden="true">N</span> Arise Notes</span><span class="browser-sim-label">SIMULATED BROWSER</span></div><div class="browser-toolbar"><span class="browser-history" aria-hidden="true">← &nbsp; →</span><button id="browser-reload" class="secondary" aria-label="Reload notes in simulated browser" title="Send GET /api/notes">↻</button><div class="browser-address"><span aria-hidden="true">▣</span> https://notes.example/</div></div><div class="browser-page"><div class="browser-app-heading"><div><span class="browser-app-label">YOUR PRACTICE APP</span><h3>My learning notes</h3></div><span id="browser-status" class="browser-status">Ready</span></div><p class="browser-help">Add a note here to send a POST request. Reload to fetch the list with GET.</p><form id="browser-note-form"><label for="browser-note">New note</label><div class="browser-compose"><input id="browser-note" placeholder="What did you learn?" maxlength="100" autocomplete="off"><button id="browser-add" class="primary">Add note</button></div></form><div id="api-screen" aria-live="polite">Your notes appear here after a successful request.</div><div class="browser-page-footer">Frontend: HTML + CSS + JavaScript <span id="browser-network-state">No API request yet</span></div></div></div><div class="inspector-heading"><h3>Behind the page</h3><span>The same request, seen as HTTP messages</span></div><div class="code-pair"><div class="code-pane"><h3>HTTP request · readable view</h3><pre id="api-request"></pre></div><div class="code-pane"><h3>HTTP response</h3><pre id="api-response"></pre></div></div>
</div><aside class="lab-card"><div class="eyebrow">FOLLOW THE CONTRACT</div><h2 id="api-teach-title">An API is an agreed interface.</h2><p id="api-teach">The frontend knows which URL and method to use, what data to send, and how to read the response. The backend can change its internals while keeping that contract.</p><ul class="check-list"><li id="api-check-request">1. Frontend prepares the request</li><li id="api-check-server">2. Backend checks and processes it</li><li id="api-check-response">3. Response updates the interface</li></ul><div class="challenge"><strong>Try it</strong><p>Create a note, then switch to GET and load the list. Next, try invalid data: an error response should not add a note.</p></div><small>In-page simulation: no real login or database. Reset clears the example notes.</small></aside></div>
<div class="reference-row"><article><h3>Frontend development</h3><p>Build accessible interfaces, layouts, and browser interactions. JavaScript can use <code>fetch('/api/notes')</code> to ask for data without reloading a page.</p><p>Client-side validation helps the user, but the server must validate too. Browser code and embedded secrets can be inspected.</p></article><article><h3>Backend development</h3><p>Define API routes, enforce permissions, validate inputs, apply business rules, and read or write data. Never trust a request just because it came from your UI.</p><p>A browser calls an API; it normally does not connect directly to your private database.</p></article><article><h3>How the app is served</h3><p>First the browser loads HTML, CSS, and JavaScript from a server or CDN. The running frontend can then fetch data. Server-rendered apps can include data in the initial HTML.</p><button class="link-button" data-jump="network">Follow DNS through HTTPS →</button><p>Cross-origin APIs also need appropriate CORS policy; CORS is not authentication.</p></article></div>`);
const terminalMarkup=(prefix)=>`<div class="terminal"><div class="terminal-bar">${prefix==='work'?'<span class="terminal-tab">TERMINAL</span>':windowDots+'<span class="window-title">learner — project</span>'}<span id="${prefix}-shell-name">bash</span></div><div class="terminal-output" id="${prefix}-output" role="log" aria-label="${prefix==='work'?'Workflow':'Shell'} terminal output" aria-live="polite"></div><form class="term-form" id="${prefix}-form"><span class="terminal-prompt" aria-hidden="true">❯</span><input id="${prefix}-command" aria-label="${prefix==='work'?'Workflow command':'Shell command'}" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="${prefix==='work'?'make':'Type pwd to begin'}"><button class="terminal-run" type="submit" title="Run command (Enter)">Run ↵</button></form><div class="terminal-details"><span id="${prefix}-cwd"></span><span id="${prefix}-exit">exit 0</span></div></div>`;
panel('shell',intro('03','Get comfortable at the prompt.','Explore files, connect commands, and see where Bash and Zsh behave differently.','15 MIN')+`
<div class="learning-grid"><div><div class="shell-mode"><label for="shell-mode">Shell</label><select id="shell-mode"><option value="bash">Bash</option><option value="zsh">Zsh</option></select><button id="shell-reset" class="secondary">Reset practice files</button><small>Virtual project · no access to your computer</small></div>${terminalMarkup('shell')}<div class="lab-card" style="margin-top:18px"><h3>Files in your current directory</h3><pre id="shell-files" class="hint-code"></pre><small>↑ / ↓ recall commands. Tab completes a unique command name. Type <code>help</code> for the supported subset.</small></div></div><aside class="lab-card"><div class="eyebrow">GUIDED PRACTICE</div><div class="task-picker" id="shell-tasks"></div><div id="task-goal" class="task-goal"></div><button id="task-hint" class="secondary">Show a hint</button><pre id="task-hint-code" class="hint-code" hidden></pre><p id="task-feedback" aria-live="polite"></p></aside></div>
<div class="reference-row"><article><h3>Terminal ≠ shell</h3><p>The terminal is the text interface. Bash and Zsh are shells: they parse your command, expand variables and filenames, and launch programs. An IDE can embed a terminal.</p><p><code>pwd</code> prints your directory. <code>cd ..</code> moves to its parent. Relative paths start at the current directory; absolute paths start at <code>/</code>.</p></article><article><h3>Text is a useful interface</h3><p><code>cat access.log | grep 404</code> sends one command’s standard output into the next command’s standard input.</p><p><code>&gt;</code> overwrites a file; <code>&gt;&gt;</code> appends. Quotes keep spaces together. Single quotes preserve <code>$NAME</code>; double quotes expand it.</p><p>Exit status <code>0</code> usually means success. <code>grep</code> uses <code>1</code> when it finds no matching lines.</p></article><article><h3>Bash and Zsh</h3><p>Most basics here are shared. With default settings, an unmatched <code>*.csv</code> stays literal in Bash, while Zsh reports “no matches found.” Settings can change this.</p><p><code>~/.bashrc</code> and <code>~/.zshrc</code> commonly configure interactive shells. Bash login shells use different startup files. This simulator does not load startup files.</p><p><code>$SHELL</code> usually names your login shell on a real machine; here it reflects the selected simulation mode.</p></article></div>`);
panel('workflow',intro('04','Edit it. Build it. See it.','Use an IDE-style editor and terminal together. Make decides which work needs to run.','15 MIN')+`
<div class="learning-grid"><div class="ide-window"><div class="ide-titlebar">${windowDots}<span class="window-title">project — Arise Code</span><span class="simulation-badge">SIMULATION</span></div><div class="ide-workspace"><nav class="file-explorer" aria-label="Project files"><div class="explorer-heading">EXPLORER</div><div class="project-folder">⌄ PROJECT</div><div class="explorer-folder">⌄ src</div><button data-editor-file="src/index.html" class="active"><span class="file-icon">&lt;&gt;</span> index.html</button><button data-editor-file="Makefile"><span class="file-icon make-icon">M</span> Makefile</button></nav><div class="editor-grid"><div class="editor"><div class="editor-toolbar"><select id="editor-file" aria-label="File to edit"><option value="src/index.html">src/index.html</option><option value="Makefile">Makefile</option></select><button id="editor-save" class="primary">Save file</button></div><div class="editor-breadcrumb" id="editor-breadcrumb">project / src / index.html</div><div class="editor-code"><pre id="editor-lines" class="editor-lines" aria-hidden="true">1</pre><textarea id="editor-text" aria-label="File contents" spellcheck="false" wrap="off" autocapitalize="off" autocomplete="off"></textarea></div><div id="editor-status" class="editor-status">Saved virtual file</div></div><div class="preview-box"><div class="preview-tabbar"><span class="tab-favicon" aria-hidden="true">↗</span> Preview</div><div class="preview-address"><span aria-hidden="true">⊙</span> localhost:3000 <span class="simulation-badge">SIMULATED</span></div><div id="work-placeholder" class="preview-placeholder"><span class="preview-empty-icon" aria-hidden="true">▤</span><strong>Your page will appear here</strong><span>Run <code>make serve</code> in the terminal to start the preview.</span></div><iframe id="work-preview" title="Simulated website preview" sandbox="" hidden></iframe><div class="editor-status" id="artifact-status">No build yet</div></div></div></div><div class="workflow-track"><span id="track-save">1 / Save source</span><span id="track-build">2 / Make build</span><span id="track-serve">3 / Serve output</span></div><div class="lesson-controls"><button class="secondary" data-work="make">make</button><button class="secondary" data-work="make build">make build</button><button class="secondary" data-work="make test">make test</button><button class="secondary" data-work="make serve">make serve</button><button class="secondary" data-work="make clean">make clean</button><button id="work-reset" class="secondary">Reset project</button></div><div class="workflow-terminal">${terminalMarkup('work')}</div></div>
<aside class="lab-card"><div class="eyebrow">BUILD YOUR FIRST PAGE</div><h2>Three tools, one project.</h2><p>The editor saves files. The terminal passes commands to a shell. <code>make</code> reads targets and prerequisites from the Makefile, then runs the needed recipes.</p><ul class="check-list" id="work-checks"><li id="work-check-edit">1. Change the heading and save</li><li id="work-check-build">2. Run make build</li><li id="work-check-skip">3. Run it again: nothing changed</li><li id="work-check-serve">4. Preview with make serve</li></ul><p id="work-feedback" aria-live="polite"></p><div class="challenge"><strong>Break it, then fix it</strong><p>Remove the <code>&lt;h1&gt;</code> and save, then run <code>make</code>. The test fails before the build. Restore the heading and try again.</p></div><small>Commands and files are simulated. The preview renders HTML in a sandbox with scripts disabled. Reloading resets your practice project.</small></aside></div>
<div class="reference-row"><article><h3>Read a Make rule</h3><p><code>dist/index.html: src/index.html</code></p><p>The target is the output. The prerequisite is an input. Make rebuilds when the output is missing or an input is newer. Save the source after building and try again.</p><p>Recipe lines begin with a TAB. In this editor, Tab inserts a tab character. A real Makefile can customize the recipe prefix.</p></article><article><h3>What .PHONY means</h3><p><code>.PHONY: all build test serve clean</code> marks action names that do not stand for files. Their prerequisites are still checked normally.</p><p><code>make</code> uses the first ordinary target, <code>all</code>. Our serial simulation visits <code>test</code>, then <code>build</code>. Real parallel Make needs explicit dependencies for required ordering.</p></article><article><h3>Development vs production</h3><p>An IDE’s Run button often launches a command in its integrated terminal. A development server can watch source files and refresh the browser. This exercise rebuilds only when you ask.</p><p>Production hosting serves a built artifact or runs backend code. Make automates commands; it is not the web server.</p></article></div>`);
// Start with the app the learner uses, then explain its request underneath.
const browserSimulation=document.querySelector('#lesson-foundations .api-browser');
browserSimulation.parentElement.prepend(browserSimulation);
browserSimulation.style.marginBottom='28px';
const addressContainer=browserSimulation.querySelector('.browser-address');
const addressForm=document.createElement('form');
addressForm.className='browser-address';
const addressInput=document.createElement('input');
addressInput.id='browser-url';
addressInput.type='text';
addressInput.value='https://notes.example/';
addressInput.setAttribute('aria-label','Simulated browser address');
addressInput.setAttribute('autocomplete','off');
addressInput.setAttribute('spellcheck','false');
addressInput.setAttribute('enterkeyhint','go');
addressInput.style.cssText='width:100%;min-width:0;border:0;outline-offset:4px;background:transparent;color:inherit;font:inherit;padding:0;';
addressForm.append(addressInput);
addressContainer.replaceWith(addressForm);
addressForm.addEventListener('submit',e=>{
 e.preventDefault();
 const value=addressInput.value.trim();
 let url;
 try{url=new URL(value.includes('://')?value:'https://'+value);}catch{addressInput.setCustomValidity('Enter notes.example or https://notes.example/');addressInput.reportValidity();return;}
 if(url.protocol!=='https:'||url.hostname!=='notes.example'||url.port||url.username||url.password){addressInput.setCustomValidity('This simulated browser supports https://notes.example/ only.');addressInput.reportValidity();return;}
 addressInput.setCustomValidity('');
 addressInput.value=url.href;
 el('api-scenario').value=url.pathname==='/'?'list':'missing';
 configureAPI();
 el('api-send').click();
});
addressInput.addEventListener('input',()=>addressInput.setCustomValidity(''));
let activeLesson='foundations';
function selectLesson(id,updateHash=true){if(!lessons.some(x=>x[0]===id))return;activeLesson=id;for(const [key] of lessons){const p=el('lesson-'+key),b=el('tab-'+key);p.hidden=key!==id;p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby',b.id);b.setAttribute('aria-selected',String(key===id));b.tabIndex=key===id?0:-1;}if(id!=='network'&&typeof setPlaying==='function')setPlaying(false);if(updateHash)history.replaceState(null,'','#'+id);}
nav.addEventListener('click',e=>{const b=e.target.closest('[data-lesson]');if(b)selectLesson(b.dataset.lesson);});
nav.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=lessons.findIndex(x=>x[0]===activeLesson),next=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;selectLesson(lessons[next][0]);el('tab-'+lessons[next][0]).focus();});
document.querySelectorAll('[data-jump]').forEach(b=>b.addEventListener('click',()=>selectLesson(b.dataset.jump)));
window.addEventListener('hashchange',()=>selectLesson(location.hash==='#takeaway'?'network':location.hash.slice(1),false));
selectLesson(location.hash==='#takeaway'?'network':lessons.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'foundations',false);

// API lesson: freeze each request at send time; commit successful POSTs once.
let notes=['Understand DNS','Try a shell command'],apiStep=0,apiTimer=null,request=null;
const apiTexts=['Ready. Send a request or use Next step to begin.','1 / Frontend prepares an HTTP request.','2 / The request travels to the API server.','3 / Backend validates the route, login, and input.','4 / Backend processes the request and prepares a response.','5 / HTTP response travels back to the browser.','6 / Frontend reads the status and updates the interface.'];
function configureAPI(){clearInterval(apiTimer);apiTimer=null;apiStep=0;request=null;const mode=el('api-scenario').value;el('api-method').value=['create','invalid'].includes(mode)?'POST':'GET';el('api-path').value=mode==='missing'?'/api/missing':'/api/notes';if(mode==='invalid')el('note-text').value='';el('note-text').disabled=!['create','invalid'].includes(mode);drawAPI();drawBrowser();}
function beginAPI(){const mode=el('api-scenario').value;request={mode,method:el('api-method').value,path:el('api-path').value,text:el('note-text').value.trim(),committed:false};apiStep=1;drawAPI();drawBrowser();}
function responseFor(r){if(r.mode==='auth')return [401,{error:'Login required'}];if(r.mode==='missing')return [404,{error:'Route not found'}];if(r.mode==='offline')return [503,{error:'Service unavailable'}];if(r.method==='POST'&&!r.text)return [422,{error:'Note text must not be empty'}];return r.method==='POST'?[201,{id:notes.length,text:r.text}]:[200,{notes:[...notes]}];}
function nextAPI(){if(!request||apiStep>=6){beginAPI();return;}apiStep++;if(apiStep===4){if(request.method==='POST'&&responseFor(request)[0]===201&&!request.committed){notes.push(request.text);request.committed=true;}request.response=responseFor(request);}drawAPI();drawBrowser();}
function drawAPI(){el('api-status').textContent=apiTexts[apiStep];document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',apiStep===1||apiStep===6?b.dataset.role==='frontend':apiStep===3?b.dataset.role==='backend':apiStep===4&&request?.response?.[0]<300?b.dataset.role==='database':false));for(const n of [1,2]){const w=el('api-wire-'+n);w.classList.toggle('active',n===1?[2,5].includes(apiStep):apiStep===4&&request?.response?.[0]<300);w.classList.toggle('returning',apiStep===5);}el('api-request').textContent=request?`${request.method} ${request.path}\nAccept: application/json\n${request.mode==='auth'?'(No session cookie)':'Cookie: session=demo'}${request.method==='POST'?'\nContent-Type: application/json\n\n'+JSON.stringify({text:request.text},null,2):''}`:'Choose a scenario to inspect its request.';el('api-response').textContent=apiStep>=4?`HTTP ${request.response[0]}\nContent-Type: application/json\n\n${JSON.stringify(request.response[1],null,2)}`:'Waiting for a response…';el('api-check-request').classList.toggle('done',apiStep>=1);el('api-check-server').classList.toggle('done',apiStep>=4);el('api-check-response').classList.toggle('done',apiStep>=6);if(apiStep>0&&apiStep<6)el('api-screen').textContent='Loading…';else if(apiStep===6){if(request.response[0]>=400)el('api-screen').textContent=`Could not load or save notes: ${request.response[1].error}.`;else{const ul=document.createElement('ul');for(const text of notes){const li=document.createElement('li');li.textContent=text;ul.append(li);}el('api-screen').replaceChildren(ul);}}else el('api-screen').textContent='Your notes appear here after a successful request.';}
el('api-scenario').addEventListener('change',configureAPI);el('api-next').addEventListener('click',()=>{clearInterval(apiTimer);apiTimer=null;nextAPI();});el('api-send').addEventListener('click',()=>{clearInterval(apiTimer);beginAPI();apiTimer=setInterval(()=>{nextAPI();if(apiStep===6){clearInterval(apiTimer);apiTimer=null;}},900);});el('api-reset').addEventListener('click',()=>{notes=['Understand DNS','Try a shell command'];configureAPI();});
function drawBrowser(){const busy=apiStep>0&&apiStep<6,error=apiStep===6&&request.response[0]>=400;el('browser-status').textContent=busy?'Loading…':error?'Request failed':apiStep===6?'Up to date':'Ready';el('browser-status').dataset.state=busy?'loading':error?'error':apiStep===6?'success':'ready';el('api-screen').setAttribute('aria-busy',String(busy));el('api-screen').classList.toggle('browser-error',error);el('browser-add').disabled=busy;el('browser-reload').disabled=busy;el('browser-network-state').textContent=apiStep===6?`${request.method} ${request.path} · ${request.response[0]}`:busy?`${request.method} ${request.path} · pending`:'No API request yet';}
el('browser-note-form').addEventListener('submit',e=>{e.preventDefault();if(apiStep>0&&apiStep<6)return;el('api-scenario').value='create';configureAPI();el('note-text').value=el('browser-note').value;el('api-send').click();});
el('browser-reload').addEventListener('click',()=>{el('api-scenario').value='list';configureAPI();el('api-send').click();});
const roleCopy={frontend:['Frontend: interaction and presentation.','It handles a click, sends the request, shows a loading state, then displays data or an error. It should not contain private API credentials.'],backend:['Backend: rules and permissions.','The API validates data, verifies identity, and decides what is allowed. It returns a status code and a body; JSON is common, but APIs can use other formats.'],database:['Database: stored application data.','The backend reads or changes records. A real database can outlive a server process; these example notes live only in page memory. Reset or reload clears them.']};
document.querySelectorAll('[data-role]').forEach(b=>b.addEventListener('click',()=>{const c=roleCopy[b.dataset.role];el('api-teach-title').textContent=c[0];el('api-teach').textContent=c[1];}));configureAPI();

function connectTerminal(prefix,engine,onRun){let historyIndex=0;const output=el(prefix+'-output'),input=el(prefix+'-command');function append(text,type){const row=document.createElement('div');row.className=type||'';row.textContent=text;output.append(row);while(output.children.length>200)output.firstChild.remove();output.scrollTop=output.scrollHeight;}function refresh(){el(prefix+'-cwd').textContent=engine.cwd;el(prefix+'-shell-name').textContent=engine.shell;}
 function run(line){if(!line.trim())return;append(`${engine.shell} ${engine.cwd.replace(engine.home,'~')} $ ${line}`,'cmd');const result=engine.run(line);if(line.trim()==='clear'&&result.code===0)output.replaceChildren();else if(result.output)append(result.output,result.code?'error':'');el(prefix+'-exit').textContent='exit '+result.code;historyIndex=engine.history.length;refresh();onRun(line,result);return result;}
 el(prefix+'-form').addEventListener('submit',e=>{e.preventDefault();const line=input.value;input.value='';run(line);});input.addEventListener('keydown',e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();historyIndex=Math.max(0,Math.min(engine.history.length,historyIndex+(e.key==='ArrowUp'?-1:1)));input.value=engine.history[historyIndex]||'';}if(e.key==='Tab'&&!input.value.includes(' ')){const matches=['pwd','ls','cd','cat','echo','mkdir','touch','cp','grep','wc','export','printenv','history','clear','bash','zsh','make','help'].filter(c=>c.startsWith(input.value));if(matches.length===1){e.preventDefault();input.value=matches[0]+' ';}}});refresh();append('Practice environment ready. Type help for supported commands.');return {run,refresh,clear(){output.replaceChildren();input.value='';historyIndex=0;el(prefix+'-exit').textContent='exit 0';refresh();append('Practice environment reset. Type help for supported commands.');}};}
const shell=new Shell();let taskIndex=0;const passed=new Set();
const tasks=[
 ['Find your place','Print the working directory, then list the files.','pwd\nls',()=>shell.events.some(e=>e.line.trim()==='pwd'&&!e.code)&&shell.events.some(e=>e.line.trim()==='ls'&&!e.code)],
 ['Read a source file','Move into src and read index.html. Use cd .. to return afterward.','cd src\ncat index.html',()=>shell.events.some(e=>e.line.trim()==='cat index.html'&&!e.code&&e.output.includes('<h1>'))],
 ['Connect commands','Return to the project directory. Count the 200 responses in access.log using a pipe.','cd ~/project\ncat access.log | grep 200 | wc -l',()=>shell.events.some(e=>e.line.includes('|')&&e.line.includes('grep 200')&&e.line.includes('wc -l')&&e.output.trim()==='3')],
 ['Variables & quotes','Export NAME with the value Arise, then print it using echo and double quotes.','export NAME=Arise\necho "$NAME"',()=>shell.env.NAME==='Arise'&&shell.events.some(e=>e.line.includes('echo')&&e.line.includes('$NAME')&&e.output.trim()==='Arise')],
 ['Write a file','Create greeting.txt containing Hello Arise, then read it back.','echo "Hello Arise" > greeting.txt\ncat greeting.txt',()=>shell.events.some(e=>e.line.trim()==='cat greeting.txt'&&!e.code&&e.output.trim()==='Hello Arise')],
 ['Compare shells','In the project directory, run echo *.csv in Bash and Zsh. There are no CSV files. See how default glob behavior differs.','bash\ncd ~/project\necho *.csv\nzsh\necho *.csv',()=>shell.events.some(e=>e.line.trim()==='echo *.csv'&&e.output.trim()==='*.csv')&&shell.events.some(e=>e.line.trim()==='echo *.csv'&&e.output.includes('no matches found'))]
];
function showTask(){el('shell-tasks').replaceChildren(...tasks.map((t,i)=>{const b=document.createElement('button');b.textContent=`${i+1}. ${t[0]}`;b.className=(taskIndex===i?'selected ':'')+(passed.has(i)?'done':'');b.addEventListener('click',()=>{taskIndex=i;showTask();});return b;}));el('task-goal').textContent=tasks[taskIndex][1];el('task-hint-code').textContent=tasks[taskIndex][2];el('task-hint-code').hidden=true;el('task-feedback').textContent=passed.has(taskIndex)?'Completed. Choose another exercise or keep experimenting.':'';}
function shellUpdated(){tasks.forEach((t,i)=>{if(t[3]())passed.add(i);});el('shell-files').textContent=shell.children().join('\n');el('shell-mode').value=shell.shell;showTask();}
const shellTerm=connectTerminal('shell',shell,shellUpdated);el('task-hint').addEventListener('click',()=>el('task-hint-code').hidden=!el('task-hint-code').hidden);el('shell-mode').addEventListener('change',e=>shellTerm.run(e.target.value));el('shell-reset').addEventListener('click',()=>{shell.reset();passed.clear();taskIndex=0;shellTerm.clear();shellUpdated();});shellUpdated();

const work=new Shell();const drafts=new Map();const sourcePath='/home/learner/project/src/index.html',buildPath='/home/learner/project/dist/index.html';let editorFile='src/index.html',savedEdit=false,builtEdit=false,skipped=false,servedEdit=false;
function syncEditorChrome(){const t=el('editor-text');el('editor-lines').textContent=Array.from({length:t.value.split('\n').length},(_,i)=>i+1).join('\n');el('editor-lines').scrollTop=t.scrollTop;el('editor-breadcrumb').textContent='project / '+editorFile.replaceAll('/',' / ');document.querySelectorAll('[data-editor-file]').forEach(b=>{b.classList.toggle('active',b.dataset.editorFile===editorFile);b.setAttribute('aria-pressed',String(b.dataset.editorFile===editorFile));});}
function loadEditor(){el('editor-text').value=drafts.get(editorFile)??work.read('/home/learner/project/'+editorFile);el('editor-status').textContent=drafts.has(editorFile)?'Unsaved changes — Save file before building':'Saved virtual file · Tab inserts indentation; Escape focuses Save';syncEditorChrome();}
function workUpdated(line='',result={code:0,output:''}){const source=work.files.get(sourcePath),artifact=work.files.get(buildPath);if(artifact&&savedEdit&&artifact.time>=source.time)builtEdit=true;if(line.trim()==='make build'&&!result.code&&result.output.includes('up to date')&&builtEdit)skipped=true;if(work.served&&builtEdit&&artifact?.time>=source.time)servedEdit=true;el('track-save').classList.toggle('done',savedEdit);el('track-build').classList.toggle('done',!!artifact&&artifact.time>=source.time);el('track-serve').classList.toggle('done',work.served);for(const [id,done] of [['edit',savedEdit],['build',builtEdit],['skip',skipped],['serve',servedEdit]])el('work-check-'+id).classList.toggle('done',done);el('artifact-status').textContent=!artifact?'No build yet':artifact.time<source.time?'Build is older than source. Run make build.':'Build matches the saved source.';if(work.served&&artifact){el('work-preview').hidden=false;el('work-placeholder').hidden=true;el('work-preview').srcdoc='<meta http-equiv="Content-Security-Policy" content="default-src \'none\'; style-src \'unsafe-inline\'"><style>body{font:16px system-ui;padding:20px;color:#162337}h1{color:#94571b}</style>'+artifact.text;}else{el('work-preview').hidden=true;el('work-placeholder').hidden=false;}el('work-feedback').textContent=result.code?'The command failed. Read its message, fix the input, and try again.':savedEdit&&builtEdit&&skipped&&servedEdit?'Complete! You edited, built, skipped unchanged work, and served your page.':'Save a new heading, then follow the checklist.';}
const workTerm=connectTerminal('work',work,workUpdated);el('editor-file').addEventListener('change',e=>{editorFile=e.target.value;loadEditor();});el('editor-text').addEventListener('input',()=>{drafts.set(editorFile,el('editor-text').value);el('editor-status').textContent='Unsaved changes — Save file before building';});el('editor-text').addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();el('editor-save').focus();}if(e.key==='Tab'){e.preventDefault();const t=e.target;t.setRangeText('\t',t.selectionStart,t.selectionEnd,'end');drafts.set(editorFile,t.value);el('editor-status').textContent='Unsaved changes — Save file before building';}});
el('editor-save').addEventListener('click',()=>{try{work.write('/home/learner/project/'+editorFile,el('editor-text').value);drafts.delete(editorFile);if(editorFile==='src/index.html')savedEdit=el('editor-text').value.includes('<h1>')&&!el('editor-text').value.includes('<h1>Hello, Arise!</h1>');el('editor-status').textContent='Saved. Your terminal sees this file immediately.';workUpdated();}catch(e){el('editor-status').textContent=e.message;}});document.querySelectorAll('[data-work]').forEach(b=>b.addEventListener('click',()=>workTerm.run(b.dataset.work)));el('work-reset').addEventListener('click',()=>{work.reset();drafts.clear();savedEdit=builtEdit=skipped=servedEdit=false;editorFile='src/index.html';el('editor-file').value=editorFile;loadEditor();workTerm.clear();workUpdated();});loadEditor();workUpdated();

// Keep the minimal IDE chrome in sync with the editable virtual files.
document.querySelectorAll('[data-editor-file]').forEach(b=>b.addEventListener('click',()=>{el('editor-file').value=b.dataset.editorFile;el('editor-file').dispatchEvent(new Event('change'));}));
el('editor-text').addEventListener('input',syncEditorChrome);
el('editor-text').addEventListener('scroll',syncEditorChrome);
el('editor-text').addEventListener('keydown',e=>{if(e.key==='Tab')syncEditorChrome();if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();el('editor-save').click();}});
